var x = 5;

let age = 20;
if (age >= 18) {
  console.log("Adult");
} else {
  console.log("Minor");
}

let fruit = 'apple';
switch (fruit) {
  case 'apple':
    console.log('It’s an apple');
    break;
  default:
    console.log('Unknown fruit');
}

for (let i = 0; i < 5; i++) {
  console.log(i);
}

let j = 0;
while (j < 5) {
  console.log(j);
  j++;
}

do {
  console.log(j);
  j++;
} while (j < 10);

function greet(name) {
  return `Hello, ${name}`;
}

const greetArrow = (name = 'Guest') => `Hello, ${name}`;

function sum(...nums) {
  return nums.reduce((a, b) => a + b, 0);
}

function outer() {
  let count = 0;
  return function inner() {
    count++;
    return count;
  };
}

const counter = outer();
console.log(counter()); // 1
console.log(counter()); // 2

try {
  throw new Error("Something went wrong");
} catch (err) {
  console.error(err.message);
} finally {
  console.log("Cleanup actions");
}

console.log("Normal log");
console.error("This is an error");
console.table([{ name: "Alice" }, { name: "Bob" }]);
debugger; // Pauses in DevTools

